<?php require 'config.php'; require_role('student'); $title='Attendance'; $u=$_SESSION['user'];
$q=$pdo->prepare("SELECT ar.attendance_date,ar.status,ar.note,s.code,s.name,o.section FROM attendance_records ar JOIN subject_offerings o ON o.id=ar.offering_id JOIN subjects s ON s.id=o.subject_id WHERE ar.student_id=? ORDER BY ar.attendance_date DESC, s.code LIMIT 100");$q->execute([$u['id']]);$rows=$q->fetchAll();
$counts=['Present'=>0,'Late'=>0,'Absent'=>0,'Excused'=>0];foreach($rows as $r){$counts[$r['status']]++;} $total=count($rows);$rate=$total?round((($counts['Present']+$counts['Excused'])/$total)*100):0;
require 'header.php'; ?><section class="section"><div class="section-intro"><div><span class="eyebrow">ACADEMIC</span><h2>Attendance</h2><p class="muted">View attendance records posted by your professors.</p></div></div><div class="enrollment-overview"><div><span>Attendance Rate</span><strong><?=$rate?>%</strong></div><div><span>Present</span><strong><?=$counts['Present']?></strong></div><div><span>Late / Absent</span><strong><?=$counts['Late']?> / <?=$counts['Absent']?></strong></div></div><?php if(!$rows):?><div class="info-box"><b>No attendance records yet.</b><p>Your attendance will appear here after your professor records it.</p></div><?php else:?><div class="table-scroll"><table class="table"><tr><th>Date</th><th>Subject</th><th>Section</th><th>Status</th><th>Note</th></tr><?php foreach($rows as $r):?><tr><td><?=date('M d, Y',strtotime($r['attendance_date']))?></td><td><b><?=e($r['code'])?></b><br><small><?=e($r['name'])?></small></td><td><?=e($r['section'])?></td><td><span class="badge <?=strtolower($r['status'])==='present'||strtolower($r['status'])==='excused'?'approved':(strtolower($r['status'])==='late'?'pending':'rejected')?>"><?=e($r['status'])?></span></td><td><?=e($r['note']?:'—')?></td></tr><?php endforeach;?></table></div><?php endif;?></section><?php require 'footer.php'; ?>
